// Paste into the browser console on vahan.parivahan.gov.in/vahan4dashboard/vahan/view/reportview.xhtml
// after the page has loaded. Captures state-by-month two-wheeler tables, all fuels and electric.
// Element ids such as j_idt71 are generated by the site and can change. Check them first.
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const idle=async()=>{for(let i=0;i<80;i++){await sleep(500);if(PrimeFaces.ajax.Queue.isEmpty())break}await sleep(600)};
const sel=(id,v)=>Object.values(PrimeFaces.widgets).find(w=>w&&w.id===id).selectValue(v);
const lab=x=>(document.querySelector(`label[for="${x.id}"]`)||{innerText:''}).innerText.trim();
const read=()=>{const h=document.getElementById('groupingTable_head'),b=document.getElementById('groupingTable_data');
  return {mo:[...h.rows[2].cells].map(c=>c.innerText.trim()),rows:[...b.rows].map(r=>[...r.cells].map(c=>c.innerText.trim()))}};
async function one(y,m){
  sel('selectedYear',String(y));await idle();
  document.getElementById('j_idt71').click();await idle();await sleep(1000);      // main refresh applies the year
  document.querySelectorAll('input[id^="VhClass:"]').forEach(x=>{x.checked=/^(M-CYCLE\/SCOOTER|MOPED|MOTORISED CYCLE|MOTOR CYCLE\/SCOOTER)/.test(lab(x))});
  document.querySelectorAll('input[id^="fuel:"]').forEach(x=>{x.checked=(m==='ev')&&/^(ELECTRIC\(BOV\)|PURE EV)$/.test(lab(x))});
  document.getElementById('j_idt86').click();await idle();await sleep(1000);      // side-panel refresh applies the filters
  const a=read();let rows=a.rows.slice(),g=0;
  while(g++<4){const cur=document.getElementById('groupingTable_data').rows[0]?.cells[1]?.innerText;
    const n=document.querySelector('.ui-paginator-next');if(!n||n.classList.contains('ui-state-disabled'))break;
    n.click();await idle();const b=read();if(b.rows[0]?.[1]===cur)break;rows=rows.concat(b.rows)}
  return {y,m,mo:a.mo,rows}}
(async()=>{sel('yaxisVar','State');await idle();sel('xaxisVar','Month Wise');await idle();sel('selectedYearType','C');await idle();
  const out=[];for(const y of [2021,2017,2018,2019,2020,2022,2023,2024,2025,2026])for(const m of ['all','ev'])out.push(await one(y,m));
  const L=[];for(const s of out){L.push(`#${s.y} ${s.m} ${s.mo.join(' ')}`);for(const r of s.rows)L.push(r[1]+' '+r.slice(2).map(v=>v.replace(/,/g,'')).join(' '))}
  console.log(L.join('\n'))})();
